package com.bank.composite;

import java.math.BigDecimal;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.SQLException;
import java.util.logging.Logger;

public class LineItemDao {
    private static final Logger log = Logger.getLogger(LineItemDao.class.getName());
    private final Connection conn;

    public LineItemDao(Connection conn) { this.conn = conn; }

    public boolean addLine(String txnId, int lineNo, String biller, BigDecimal amount) {
        String sql = "INSERT INTO transaction_lines (txn_id, line_no, biller, amount) VALUES (?,?,?,?)";
        try (PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, txnId);
            ps.setInt(2, lineNo);
            ps.setString(3, biller);
            ps.setBigDecimal(4, amount);
            ps.executeUpdate();
            log.info(() -> "Added line " + txnId + "#" + lineNo + " " + biller);
            return true;
        } catch (SQLException e) {
            log.severe("Rejected " + txnId + "#" + lineNo + ": " + e.getMessage());
            return false;
        }
    }
}
