package com.bank.composite;

import java.math.BigDecimal;
import java.sql.Connection;
import java.sql.DriverManager;
import java.util.logging.Logger;

public class CompositeKeyDemo {
    private static final Logger log = Logger.getLogger(CompositeKeyDemo.class.getName());

    public static void main(String[] args) throws Exception {
        try (Connection conn = DriverManager.getConnection(
                "jdbc:postgresql://localhost:5432/bankdb", "bank_app", "secret")) {
            LineItemDao dao = new LineItemDao(conn);

            // Same line_no=1 across different txns is fine — only the PAIR must be unique.
            dao.addLine("TXN-0003", 1, "GAS", new BigDecimal("1200.00"));  // OK

            // Duplicate composite key (TXN-0001, 1 already exists) → rejected.
            dao.addLine("TXN-0001", 1, "BROADBAND", new BigDecimal("999.00"));

            log.info("One composite PRIMARY KEY (txn_id,line_no); extra rules are UNIQUE constraints.");
        }
    }
}
